from pathlib import Path
import json,html,sys
root=Path(sys.argv[1]).resolve() if len(sys.argv)>1 else Path(__file__).resolve().parent.parent
brands=json.loads((root/'source/brands.json').read_text())
cards=[]
for i,b in enumerate(brands):
    pre='previews/'+b['id']+'/'
    native=pre+'index.html' if (root/pre/'index.html').exists() else pre+'desktop-design.png'
    cards.append('<article id="'+b['id']+'" style="--accent:'+b['accent']+';--ink:'+b['ink']+';--surface:'+b['surface']+'"><div class="intro"><span class="number">0'+str(i+1)+'</span><div><p class="eyebrow">'+html.escape(b['tone'])+'</p><h2>'+b['name']+'</h2><p>'+b['positioning']+'</p></div></div><div class="previews"><a class="desktop" href="'+native+'" target="_blank"><span>Desktop · 1440 px</span><img src="'+pre+'desktop-design.png" alt="'+b['name']+' desktop theme preview"></a><a class="mobile" href="'+pre+'mobile.png" target="_blank"><span>Mobile · 390 px</span><img src="'+pre+'mobile-design.png" alt="'+b['name']+' mobile theme preview"></a></div><div class="rationale"><p><strong>Identity</strong> '+b['character']+'</p><p><strong>Composition</strong> '+b['composition']+'</p><p><strong>Typography</strong> '+b['headingFont']+' / '+b['bodyFont']+'</p><p><strong>Photographic direction</strong> '+b['photoStyle']+'</p><div class="actions"><a class="button" href="'+native+'" target="_blank">Inspect full design ↗</a><a href="packages/'+b['id']+'-Legacy-BookNow-R1.zip">Theme ZIP</a><a href="'+b['url']+'" target="_blank" rel="noopener">Official brand reference ↗</a></div></div></article>')
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Five safari identities · BookNow review</title><style>
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f0f0e9;color:#263126;font:15px/1.7 Arial,sans-serif}a{color:inherit;text-underline-offset:4px}header{padding:62px max(24px,calc((100vw - 1200px)/2));background:#202a22;color:#f7f6ee;border-top:7px solid #aa9468}header .eyebrow{color:#c8bd9e}h1{font:normal clamp(36px,5vw,64px)/1.05 Georgia,serif;max-width:850px;margin:20px 0}header p{max-width:760px}.eyebrow{text-transform:uppercase;letter-spacing:.15em;font-size:11px;margin:0}nav{display:flex;flex-wrap:wrap;gap:12px 24px;margin-top:28px}nav a{font-size:13px}main{max-width:1248px;margin:auto;padding:32px 24px}article{margin:28px 0 60px;background:var(--surface);border:1px solid #c8cabe;border-top:5px solid var(--accent);scroll-margin-top:16px}.intro{display:flex;gap:24px;padding:30px 32px;border-bottom:1px solid #c8cabe}.number{font:normal 46px/1 Georgia,serif;color:var(--accent)}h2{font:normal 34px/1.2 Georgia,serif;color:var(--ink);margin:8px 0 12px}.intro p{margin:8px 0}.previews{display:grid;grid-template-columns:minmax(0,1fr) 235px;gap:26px;padding:28px 32px;background:#e5e5dc;align-items:start}.previews a{display:block;text-decoration:none;min-width:0}.previews span{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.12em;margin-bottom:10px;color:#3e483e}.previews img{display:block;width:100%;height:auto;border:1px solid #b9bdb2;box-shadow:0 6px 18px #26312616}.rationale{padding:16px 32px 30px}.rationale p{max-width:1000px;margin:12px 0}.rationale strong{display:inline-block;min-width:160px;color:var(--ink)}.actions{display:flex;flex-wrap:wrap;align-items:center;gap:20px;margin-top:24px;font-size:13px}.button{background:var(--ink);color:white;padding:10px 16px;text-decoration:none}a:focus-visible{outline:3px solid #a9752d;outline-offset:5px}aside{padding:26px 32px;border:1px solid #b7bfb0;background:#e2e7db;margin:24px 0}aside ul{padding-left:20px}footer{padding:25px 0 50px;font-size:13px}details{margin:18px 0}summary{cursor:pointer;font-weight:bold}@media(max-width:760px){header{padding:34px 20px}.intro,.rationale{padding:22px 18px}main{padding:16px}.previews{grid-template-columns:minmax(0,1fr);padding:20px 18px}.mobile{max-width:300px;margin:auto}.rationale strong{display:block}.intro{gap:14px}h2{font-size:28px}aside{padding:20px}}
</style></head><body><header><p class="eyebrow">Extraordinary / old BookNow / first design review / 25 October 2026</p><h1>Five places.<br>Five distinct arrivals.</h1><p>Property identity should continue all the way to booking. These five themes begin with each official website’s mark, typography, colour and character, then translate it into the existing booking engine.</p><p>One design per property. Desktop and mobile. Review candidates awaiting Papi’s inspection.</p><nav>'''+''.join('<a href="#'+b['id']+'">'+b['name']+'</a>' for b in brands)+'''</nav></header><main><aside><strong>What you are reviewing</strong><p>Five locally built design candidates, using property-specific native booking markup and the packaged theme CSS. Click a preview to inspect it. Logos, photography and introduction copy are separate CMS items; installing only a theme will not produce the complete content shown here.</p><details><summary>Checks and approval boundary</summary><p>All five passed local viewport checks at 320, 390, 768, 1024 and 1440 pixels: no page overflow, loaded intended fonts and visible form fields at least 44 pixels high. Original native carousel behavior is retained. Each preview uses two crops of one photograph, solely to demonstrate that mechanism.</p><p>No live installation, availability search, booking or payment occurred. Physical-device behavior, each native booking journey and CMS acceptance still need an authorised installer. Existing map and accessibility findings remain open.</p></details></aside>'''+''.join(cards)+'''<aside><strong>Papi’s review checklist</strong><ul><li>Does each design feel recognisably like its own property website?</li><li>Are the authentic logo, type and colour treatment right for the property?</li><li>Does the desktop composition and mobile reading order feel clear?</li><li>Approve or correct the proposed photograph/crop and introduction separately.</li><li>Record approval of the specific version before authorising an installer.</li></ul><p><a href="INSTALLER.md">Installer and rollback guide</a> · <a href="README.md">Source and build instructions</a> · <a href="CHANGELOG.md">Change log</a></p></aside><footer>R1 is a review candidate. Sponsor acceptance and live release are separate. R0 additional spending; included allowance consumption unknown. Source-linked brand briefs accompany every theme.</footer></main></body></html>'''
(root/'index.html').write_text(page,encoding='utf-8')
print('Five-property comparison gallery saved.')
